"""Input validation and security helpers for UE5 MCP tools.

Provides:
- AST-based Python code sandboxing for execute_python
- String sanitization for actor labels, class names, paths
- Path validation for UE content paths and blueprint paths
"""

from __future__ import annotations

import ast
import re
from typing import Optional

# ═══════════════════════════════════════════════════════════════════════════════
# PYTHON CODE SANDBOX
# ═══════════════════════════════════════════════════════════════════════════════

# Modules that must never be imported in editor Python
BLOCKED_MODULES = frozenset({
    "subprocess", "shutil", "socket", "http.server", "xmlrpc",
    "ctypes", "multiprocessing", "signal", "pty", "pipes",
    "webbrowser", "antigravity", "turtle", "tkinter",
    "smtplib", "ftplib", "telnetlib", "poplib", "imaplib",
    "nntplib", "xmlrpc.server",
})

# Attribute accesses that are dangerous even on allowed modules
BLOCKED_ATTRS = frozenset({
    "system",       # os.system
    "popen",        # os.popen
    "exec",         # builtins.exec (as attr)
    "eval",         # builtins.eval (as attr)
    "execfile",
    "spawn",        # os.spawn*
    "startfile",    # os.startfile
    "rmtree",       # shutil.rmtree
    "rmdir",        # os.rmdir
    "remove",       # os.remove
    "unlink",       # os.unlink / Path.unlink
    "rename",       # os.rename
    "replace",      # os.replace
    "makedirs",     # os.makedirs (outside project)
    "chown",
    "chmod",
    "kill",         # os.kill
})

# Functions that must never appear as Call targets
BLOCKED_BUILTINS = frozenset({
    "exec", "eval", "compile", "__import__", "breakpoint",
})


class CodeValidationError(Exception):
    """Raised when submitted code fails sandbox validation."""
    pass


def validate_python_code(code: str) -> Optional[str]:
    """Validate Python code for safety before execution in UE5.

    Returns None if safe, or an error message string if blocked.
    """
    # Parse the AST — syntax errors are caught here
    try:
        tree = ast.parse(code)
    except SyntaxError as e:
        return f"Syntax error: {e.msg} (line {e.lineno})"

    for node in ast.walk(tree):
        # Block dangerous imports
        if isinstance(node, ast.Import):
            for alias in node.names:
                mod_root = alias.name.split(".")[0]
                if alias.name in BLOCKED_MODULES or mod_root in BLOCKED_MODULES:
                    return f"Blocked import: '{alias.name}' is not allowed in editor scripts"

        elif isinstance(node, ast.ImportFrom):
            if node.module:
                mod_root = node.module.split(".")[0]
                if node.module in BLOCKED_MODULES or mod_root in BLOCKED_MODULES:
                    return f"Blocked import: 'from {node.module}' is not allowed in editor scripts"

        # Block dangerous attribute access (e.g., os.system, shutil.rmtree)
        elif isinstance(node, ast.Attribute):
            if node.attr in BLOCKED_ATTRS:
                # Check if it's on a known-dangerous module
                if isinstance(node.value, ast.Name) and node.value.id in ("os", "shutil", "pathlib"):
                    return f"Blocked operation: '{node.value.id}.{node.attr}' is not allowed"

        # Block dangerous builtin calls
        elif isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name) and func.id in BLOCKED_BUILTINS:
                return f"Blocked builtin: '{func.id}()' is not allowed in editor scripts"

    return None


# ═══════════════════════════════════════════════════════════════════════════════
# STRING SANITIZATION
# ═══════════════════════════════════════════════════════════════════════════════

# Valid UE identifier: alphanumeric, underscores, hyphens, spaces, dots
_SAFE_LABEL_RE = re.compile(r'^[\w\s\-\.()]+$', re.UNICODE)

# Valid UE class name: PascalCase identifier, no special chars
_SAFE_CLASS_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

# Valid UE content path: /Game/... or /Engine/... with safe chars
_SAFE_PATH_RE = re.compile(r'^/[A-Za-z0-9_][A-Za-z0-9_/\-\.]*$')

# Valid UE object path (includes : and . for subobject addressing)
_SAFE_OBJECT_PATH_RE = re.compile(r'^/[A-Za-z0-9_][A-Za-z0-9_/\-\.\:]*$')

# Property names: alphanumeric, underscores
_SAFE_PROPERTY_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')


def sanitize_label(label: str, param_name: str = "label") -> Optional[str]:
    """Validate an actor label. Returns error message or None if valid."""
    if not label:
        return f"{param_name} cannot be empty"
    if len(label) > 256:
        return f"{param_name} too long ({len(label)} chars, max 256)"
    if not _SAFE_LABEL_RE.match(label):
        return f"{param_name} contains invalid characters: only alphanumeric, spaces, hyphens, dots, underscores, and parentheses are allowed"
    return None


def sanitize_class_name(class_name: str, param_name: str = "class_name") -> Optional[str]:
    """Validate a UE class name. Returns error message or None if valid."""
    if not class_name:
        return f"{param_name} cannot be empty"
    if len(class_name) > 128:
        return f"{param_name} too long ({len(class_name)} chars, max 128)"
    if not _SAFE_CLASS_RE.match(class_name):
        return f"{param_name} '{class_name}' is not a valid class name (must be alphanumeric/underscores, start with letter)"
    return None


def sanitize_content_path(path: str, param_name: str = "path") -> Optional[str]:
    """Validate a UE content path (/Game/..., /Engine/...). Returns error message or None."""
    if not path:
        return f"{param_name} cannot be empty"
    if len(path) > 512:
        return f"{param_name} too long ({len(path)} chars, max 512)"
    if not _SAFE_PATH_RE.match(path):
        return f"{param_name} '{path}' is not a valid content path (must start with / and contain only safe characters)"
    if ".." in path:
        return f"{param_name} contains path traversal sequence '..'"
    return None


def sanitize_object_path(path: str, param_name: str = "object_path") -> Optional[str]:
    """Validate a UE object path (includes : and . for subobjects). Returns error message or None."""
    if not path:
        return f"{param_name} cannot be empty"
    if len(path) > 1024:
        return f"{param_name} too long ({len(path)} chars, max 1024)"
    if not _SAFE_OBJECT_PATH_RE.match(path):
        return f"{param_name} '{path}' is not a valid object path"
    if ".." in path.replace("..", ""):  # Allow single dots but not ..
        pass  # UE paths legitimately use dots
    return None


def sanitize_property_name(name: str, param_name: str = "property_name") -> Optional[str]:
    """Validate a property name. Returns error message or None."""
    if not name:
        return f"{param_name} cannot be empty"
    if len(name) > 128:
        return f"{param_name} too long ({len(name)} chars, max 128)"
    if not _SAFE_PROPERTY_RE.match(name):
        return f"{param_name} '{name}' is not a valid property name"
    return None


def make_error(message: str) -> str:
    """Create a JSON error response string."""
    import json
    return json.dumps({"error": message}, indent=2)

"""Asset management tools for UE5 MCP server."""

from __future__ import annotations

import json
import logging

logger = logging.getLogger("ue5-mcp.tools.assets")

from ._validation import sanitize_label, sanitize_class_name, make_error


def _escape_for_fstring(s: str) -> str:
    """Escape a string for safe embedding in an f-string Python code template."""
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("'", "\\'").replace("\n", "\\n")


def register(server, ue):
    @server.tool(
        name="ue_find_assets",
        description="Search the Content Browser for assets by name pattern. Returns up to 50 matches.",
        annotations={
            "readOnlyHint": True,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def find_assets(search_pattern: str, class_filter: str | None = None) -> str:
        """Search for assets. search_pattern matches against asset names (case-insensitive)."""
        if not search_pattern or len(search_pattern) > 256:
            return make_error("search_pattern must be 1-256 characters")
        if class_filter is not None:
            if err := sanitize_class_name(class_filter, "class_filter"):
                return make_error(err)

        result = await ue.find_assets(search_pattern, class_filter=class_filter)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_create_material",
        description="Create a basic material with base color, roughness, and metallic parameters.",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def create_material(
        name: str,
        base_color_r: float = 0.8,
        base_color_g: float = 0.8,
        base_color_b: float = 0.8,
        roughness: float = 0.5,
        metallic: float = 0.0,
    ) -> str:
        """Create a material instance at /Game/Materials/{name}."""
        if err := sanitize_label(name, "name"):
            return make_error(err)

        safe_name = _escape_for_fstring(name)
        code = f"""
import unreal

# Create material asset
asset_tools = unreal.AssetToolsHelpers.get_asset_tools()
factory = unreal.MaterialFactoryNew()
material = asset_tools.create_asset("{safe_name}", "/Game/Materials", unreal.Material, factory)

if material:
    # Set up base color via constant expression
    editor_subsystem = unreal.get_editor_subsystem(unreal.MaterialEditingSubsystem) if hasattr(unreal, 'MaterialEditingSubsystem') else None

    # Save the asset
    unreal.EditorAssetLibrary.save_asset("/Game/Materials/{safe_name}")
    print("RESULT:CREATED /Game/Materials/{safe_name}")
else:
    print("RESULT:FAILED")
"""
        result = await ue.execute_python(code)
        return json.dumps(result, indent=2)

"""Actor manipulation tools for UE5 MCP server."""

from __future__ import annotations

import json
import logging

from ._validation import sanitize_class_name, sanitize_label, sanitize_object_path, make_error

logger = logging.getLogger("ue5-mcp.tools.actors")


def register(server, ue):
    @server.tool(
        name="ue_spawn_actor",
        description="Spawn an actor in the UE5 editor by class name at a given location.",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": False,
        },
    )
    async def spawn_actor(
        class_name: str = "StaticMeshActor",
        x: float = 0.0,
        y: float = 0.0,
        z: float = 0.0,
        rx: float = 0.0,
        ry: float = 0.0,
        rz: float = 0.0,
        label: str | None = None,
    ) -> str:
        """Spawn an actor. class_name can be a UE class like StaticMeshActor, PointLight, CameraActor, etc."""
        if err := sanitize_class_name(class_name):
            return make_error(err)
        if label is not None:
            if err := sanitize_label(label):
                return make_error(err)

        result = await ue.spawn_actor(
            class_name,
            location=(x, y, z),
            rotation=(rx, ry, rz),
            label=label,
        )
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_delete_actor",
        description="Delete an actor from the level by its object path.",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": True,
            "idempotentHint": True,
        },
    )
    async def delete_actor(actor_path: str) -> str:
        """Delete an actor by its full object path (e.g. /Game/Maps/MainLevel.MainLevel:PersistentLevel.Cube_1)."""
        if err := sanitize_object_path(actor_path, "actor_path"):
            return make_error(err)

        result = await ue.delete_actor(actor_path)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_list_actors",
        description="List all actors in the current level, optionally filtered by class name.",
        annotations={
            "readOnlyHint": True,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def list_actors(class_filter: str | None = None) -> str:
        """List actors. Returns name, class, path, and location for each actor."""
        if class_filter is not None:
            if err := sanitize_class_name(class_filter, "class_filter"):
                return make_error(err)

        result = await ue.list_actors(class_filter=class_filter)
        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_set_transform",
        description="Set the transform (location/rotation/scale) of an actor.",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def set_transform(
        actor_path: str,
        x: float | None = None,
        y: float | None = None,
        z: float | None = None,
        rx: float | None = None,
        ry: float | None = None,
        rz: float | None = None,
        sx: float | None = None,
        sy: float | None = None,
        sz: float | None = None,
    ) -> str:
        """Set location (x,y,z), rotation (rx,ry,rz), and/or scale (sx,sy,sz) on an actor."""
        if err := sanitize_object_path(actor_path, "actor_path"):
            return make_error(err)

        location = (x, y, z) if x is not None and y is not None and z is not None else None
        rotation = (rx, ry, rz) if rx is not None and ry is not None and rz is not None else None
        scale = (sx, sy, sz) if sx is not None and sy is not None and sz is not None else None
        result = await ue.set_actor_transform(
            actor_path, location=location, rotation=rotation, scale=scale
        )
        return json.dumps(result, indent=2)

